begin;
select no_plan();
select ok(app_private.schedule_due('2024-01-31','monthly','2024-02-29'),'leap February clamps');
select ok(app_private.schedule_due('2023-01-31','monthly','2023-02-28'),'ordinary February clamps');
select ok(app_private.schedule_due('2024-01-31','monthly','2024-03-31'),'month end restores original anchor');
select ok(not app_private.schedule_due('2024-01-31','monthly','2024-03-29'),'clamp does not drift');
select ok(app_private.schedule_due('2026-10-01','daily','2026-10-04'),'daily across Sydney DST');
select ok(app_private.schedule_due('2026-09-27','weekly','2026-10-04'),'weekly calendar across DST');
select ok(app_private.schedule_due('2026-09-20','fortnightly','2026-10-04'),'fortnightly calendar');
select ok(not app_private.schedule_due('2026-10-02','daily','2026-10-01'),'future anchor does not catch up');
select is(('2026-10-03 15:00+00'::timestamptz at time zone 'Australia/Sydney')::date,'2026-10-04'::date,'IANA server calendar respects DST boundary');
insert into auth.users(id,email) values
 ('f3333333-1111-4111-8111-111111111101','schedule-owner@example.test'),
 ('f3333333-1111-4111-8111-111111111102','schedule-member@example.test');
select set_config('request.jwt.claim.sub','f3333333-1111-4111-8111-111111111102',true); select public.complete_profile('Schedule member');
select set_config('request.jwt.claim.sub','f3333333-1111-4111-8111-111111111101',true); select public.complete_profile('Schedule owner');
insert into public.groups(id,name,currency_code) values('f3333333-1111-4111-8111-111111111100','Schedules','AUD');
insert into public.group_members(group_id,user_id,display_name) values('f3333333-1111-4111-8111-111111111100','f3333333-1111-4111-8111-111111111102','Schedule member');
set local role authenticated;
select set_config('test.template',(public.save_expense_template('f3333333-1111-4111-8111-111111111100','Pinned','{"description":"Pinned draft","amount":"10.00","split_method":"equal"}')).id::text,true);
select set_config('test.schedule',(public.create_expense_schedule(current_setting('test.template')::uuid,'Daily test','daily','2000-01-01','Australia/Sydney')).id::text,true);
select is((select count(*) from public.expenses),0::bigint,'schedule creation creates no money');
select lives_ok($$select public.get_expense_schedule_page('f3333333-1111-4111-8111-111111111100')$$,'due discovery succeeds');
select is((select count(*) from public.expense_occurrences),91::bigint,'years overdue bounded to ninety days plus today');
select is(jsonb_array_length(public.get_expense_schedule_page('f3333333-1111-4111-8111-111111111100')->'occurrences'),51,'bounded page includes lookahead');
select is((select count(*) from public.expense_occurrences),91::bigint,'repeated discovery creates no duplicates');
select is((select count(*) from public.expenses),0::bigint,'discovery never posts');
select throws_ok($$update public.expense_schedules set enabled=false$$,'42501',null,'no direct schedule DML');
select throws_ok($$update public.expense_occurrences set state='completed'$$,'42501',null,'no direct occurrence DML');
select throws_ok($$select public.create_expense_schedule(current_setting('test.template')::uuid,'Invalid','daily',current_date,'Invalid/Zone')$$,'P0001','Invalid schedule configuration','unknown timezone rejected');
select public.save_expense_template('f3333333-1111-4111-8111-111111111100','Edited','{"description":"Changed template"}',id,updated_at) from public.expense_templates;
select is((select payload->>'description' from public.expense_schedules),'Pinned draft','template edit cannot mutate schedule snapshot');
select public.delete_expense_template(id,updated_at) from public.expense_templates;
select is((select template_id from public.expense_schedules),null::uuid,'template deletion retains pinned schedule');
select public.update_expense_schedule(id,revision,name,cadence,anchor_date,timezone,false) from public.expense_schedules;
select throws_ok($$select public.update_expense_schedule(id,1,name,cadence,anchor_date,timezone,true) from public.expense_schedules$$,'P0001','Schedule changed; reload before editing','stale schedule edit rejected');
select is((public.get_expense_schedule_page('f3333333-1111-4111-8111-111111111100')->'occurrences'->0->>'can_review'),'false','paused occurrence is nonactionable');
select public.update_expense_schedule(id,revision,name,cadence,anchor_date,timezone,true) from public.expense_schedules;
select public.get_expense_schedule_page('f3333333-1111-4111-8111-111111111100');
select is((select count(*) from public.expense_occurrences),91::bigint,'resume does not duplicate calendar dates');
select set_config('test.occurrence',(select id::text from public.expense_occurrences order by due_date desc limit 1),true);
select set_config('test.skipped',(select id::text from public.expense_occurrences order by due_date asc limit 1),true);
select public.skip_expense_occurrence(current_setting('test.skipped')::uuid);
select public.skip_expense_occurrence(current_setting('test.skipped')::uuid);
select is((select state from public.expense_occurrences where id=current_setting('test.skipped')::uuid),'skipped','skip replay is idempotent');
reset role;
create function pg_temp.post_occurrence(p_id uuid,p_operation uuid,p_description text default 'Explicit confirmation') returns uuid language sql as $$
 select (public.post_scheduled_expense(p_id,'f3333333-1111-4111-8111-111111111100',p_description,1000,'2026-10-01 12:00+00',
   jsonb_build_array(jsonb_build_object('member_id',m.id,'amount_minor',1000)),
   jsonb_build_array(jsonb_build_object('member_id',m.id,'amount_minor',1000)),p_operation,null)).id
 from public.group_members m where m.group_id='f3333333-1111-4111-8111-111111111100' and m.user_id='f3333333-1111-4111-8111-111111111101';
$$;
set local role authenticated;
select set_config('test.expense',pg_temp.post_occurrence(current_setting('test.occurrence')::uuid,'f3333333-1111-4111-8111-111111111199')::text,true);
select is(pg_temp.post_occurrence(current_setting('test.occurrence')::uuid,'f3333333-1111-4111-8111-111111111199')::text,current_setting('test.expense'),'lost response replays same expense');
select is(pg_temp.post_occurrence(current_setting('test.occurrence')::uuid,gen_random_uuid())::text,current_setting('test.expense'),'second reviewer operation cannot duplicate occurrence');
select throws_ok($$select pg_temp.post_occurrence(current_setting('test.occurrence')::uuid,gen_random_uuid(),'Conflicting')$$,'P0001','Occurrence already posted with different fields','conflicting occurrence replay rejected');
select throws_ok($$select pg_temp.post_occurrence(current_setting('test.skipped')::uuid,gen_random_uuid())$$,'P0001','Occurrence is not actionable','skipped proposal cannot post');
select is((select count(*) from public.expenses),1::bigint,'exactly one explicit expense');
select is((select state from public.expense_occurrences where id=current_setting('test.occurrence')::uuid),'completed','completion linked atomically to expense');
select throws_ok($$select public.skip_expense_occurrence(current_setting('test.occurrence')::uuid)$$,'P0001','A confirmed occurrence cannot be skipped','confirmed occurrence retained');
select set_config('request.jwt.claim.sub','f3333333-1111-4111-8111-111111111102',true);
select throws_ok($$select public.update_expense_schedule(id,revision,name,cadence,anchor_date,timezone,false) from public.expense_schedules$$,'P0001','Schedule is unavailable','ordinary member cannot edit creator schedule');
select is(pg_temp.post_occurrence(current_setting('test.occurrence')::uuid,gen_random_uuid())::text,current_setting('test.expense'),'different authorized account cannot post twice');
select set_config('request.jwt.claim.sub','f3333333-1111-4111-8111-111111111199',true);
select is((select count(*) from public.expense_schedules),0::bigint,'outsider RLS hides schedules');
select is((select count(*) from public.expense_occurrences),0::bigint,'outsider RLS hides proposals');
select throws_ok($$select public.get_expense_schedule_page('f3333333-1111-4111-8111-111111111100')$$,'P0001','Group is unavailable','outsider RPC denied');
select throws_ok($$select public.skip_expense_occurrence(current_setting('test.skipped')::uuid)$$,'P0001','Occurrence is unavailable','outsider cannot skip');
select set_config('request.jwt.claim.sub','f3333333-1111-4111-8111-111111111101',true);
select public.archive_group('f3333333-1111-4111-8111-111111111100');
select is(public.get_expense_schedule_page('f3333333-1111-4111-8111-111111111100')->'schedules'->0->>'can_edit','false','archive is read only');
select throws_ok($$select public.skip_expense_occurrence(current_setting('test.skipped')::uuid)$$,'P0001','Occurrence is unavailable','archive rejects mutation');
select public.reopen_group('f3333333-1111-4111-8111-111111111100');
select lives_ok($$select public.get_expense_schedule_page('f3333333-1111-4111-8111-111111111100')$$,'reopen restores discovery');
select public.archive_group('f3333333-1111-4111-8111-111111111100');
reset role;
select lives_ok($$delete from auth.users where id='f3333333-1111-4111-8111-111111111101'$$,'settled archived creator deletion preserves schedules');
select is((select count(*) from public.expense_schedules where created_by is null),1::bigint,'creator deidentified');
select is((select count(*) from public.expense_occurrences),91::bigint,'shared schedule history retained');
select set_config('request.jwt.claim.sub','f3333333-1111-4111-8111-111111111101',true);
set local role authenticated;
select throws_ok($$select public.get_expense_schedule_page('f3333333-1111-4111-8111-111111111100')$$,'P0001','Group is unavailable','deleted account old identity denied');
reset role;
select * from finish();
rollback;
